def grades_for(race: int, job: int, sub_job: int) -> tuple[dict, dict, dict]:
    """(race grades, job grades, subjob grades) for a race field and job ids."""
    race_grades = RACE_GRADES[RACE_NAMES[RACE_OF_FIELD.get(int(race), 0)]]
    job_grades = JOB_GRADES[JOB_OF_ID.get(int(job), "war")]
    if int(sub_job):
        sub_grades = JOB_GRADES[JOB_OF_ID.get(int(sub_job), "war")]
    else:
        sub_grades = NONE_GRADES
    return race_grades, job_grades, sub_grades


def _clamp_level(level: int) -> int:
    return max(0, min(99, int(level)))


def _base_stat(race_rank: int, job_rank: int, level: int, sub_rank: int, sub_level: int) -> int:
    """One attribute before gear: the retail round-once pool."""
    level = _clamp_level(level)
    sub_level = _clamp_level(sub_level)
    pooled = (HALF_POINTS[race_rank][level]
              + HALF_POINTS[job_rank][level]
              + HALF_POINTS[sub_rank][sub_level] // 2)
    return pooled // 2 + POINTS_OVER_75[level]


def base_stats(race: int, job: int, level: int,
               sub_job: int = 0, sub_level: int = 0) -> dict[str, int]:
    """The seven base attributes for a race field, job id and level pair."""
    race_rank, job_rank, sub_rank = grades_for(race, job, sub_job)
    level = _clamp_level(level)
    sub_level = _clamp_level(sub_level) if int(sub_job) else 0
    return {
        stat: _base_stat(race_rank[stat], job_rank[stat], level,
                         sub_rank[stat], sub_level)
        for stat in ATTRIBUTES
    }


def base_hp(race: int, job: int, level: int, sub_job: int = 0,
            sub_level: int = 0) -> int:
    """Retail base HP: race + job whole points, plus half of the subjob's job HP."""
    race_rank, job_rank, sub_rank = grades_for(race, job, sub_job)
    level = _clamp_level(level)
    sub_level = _clamp_level(sub_level) if int(sub_job) else 0
    race_index = RACES_INDEX[RACE_NAMES[RACE_OF_FIELD.get(int(race), 0)]]
    return (RACE_HP[race_index][level]
            + JOB_HP[job_rank["hp"]][level]
            + JOB_HP[sub_rank["hp"]][sub_level] // 2)


def base_mp(race: int, job: int, level: int, sub_job: int = 0,
            sub_level: int = 0) -> int:
    """Retail base MP.

    A job with an MP grade brings its racial MP with it.  One without (WAR, BST, ...)
    only gets MP from a subjob that has it, and then the racial part enters at the
    subjob's level, shared down like the subjob itself.
    """
    race_rank, job_rank, sub_rank = grades_for(race, job, sub_job)
    level = _clamp_level(level)
    sub_level = _clamp_level(sub_level) if int(sub_job) else 0
    race_index = RACES_INDEX[RACE_NAMES[RACE_OF_FIELD.get(int(race), 0)]]
    share = SUBJOB_MP_DIVISOR
    job_grade = job_rank["mp"]
    sub_grade = sub_rank["mp"]
    if job_grade > 0:
        total = RACE_MP[race_index][level] + JOB_MP[job_grade][level]
        if sub_grade > 0:
            total += JOB_MP[sub_grade][sub_level] // share
        return total
    if sub_grade > 0:
        return (RACE_MP[race_index][sub_level] // share
                + JOB_MP[sub_grade][sub_level] // share)
    return 0
